package com.shengyu.module.platform.api.tenant;import com.shengyu.framework.common.util.object.BeanUtils;import com.shengyu.module.platform.api.tenant.dto.packages.TenantPackageRespDTO;import com.shengyu.module.platform.service.tenant.TenantPackageService;import javax.annotation.Resource;import org.springframework.stereotype.Service;/** * 租户套餐API实现 * * @author zhusy * @since 2022/8/6 */@Servicepublic class TenantPackageApiImpl implements TenantPackageApi {    @Resource    private TenantPackageService tenantPackageService;    @Override    public TenantPackageRespDTO getTenantPackage(Long id) {        return BeanUtils.toBean(tenantPackageService.getTenantPackage(id), TenantPackageRespDTO.class);    }}